import{_ as i,o,c as l,ae as a}from"./chunks/framework.qNV68s4p.js";const u=JSON.parse('{"title":"使用概览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/usage.md","filePath":"zh/guide/usage.md","lastUpdated":1776335312000}'),t={name:"zh/guide/usage.md"};function r(n,e,s,d,c,h){return o(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="使用概览" tabindex="-1">使用概览 <a class="header-anchor" href="#使用概览" aria-label="Permalink to &quot;使用概览&quot;">​</a></h1><p>这一页从实际集成角度概述 SweetEditor 在 Compose Multiplatform 应用中的典型使用方式。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><ul><li><code>SweetEditor</code>: 编辑器 Composable 表面</li><li><code>SweetEditorController</code>: 负责编辑命令、providers、运行时集成的控制器</li><li><code>EditorState</code>: 编辑器状态与平台桥接生命周期</li><li><code>EditorDocument</code>: 当前活动文档桥接对象</li></ul><h2 id="典型集成流程" tabindex="-1">典型集成流程 <a class="header-anchor" href="#典型集成流程" aria-label="Permalink to &quot;典型集成流程&quot;">​</a></h2><ol><li>创建或 remember 一个 <code>SweetEditorController</code></li><li>将文档加载到控制器中</li><li>按需附加 completion providers 或 decoration providers</li><li>渲染 <code>SweetEditor</code></li><li>通过 controller 的 event bus 响应编辑器事件</li></ol><h2 id="常见扩展点" tabindex="-1">常见扩展点 <a class="header-anchor" href="#常见扩展点" aria-label="Permalink to &quot;常见扩展点&quot;">​</a></h2><h3 id="decorations" tabindex="-1">Decorations <a class="header-anchor" href="#decorations" aria-label="Permalink to &quot;Decorations&quot;">​</a></h3><p>你可以通过 decoration providers 添加：</p><ul><li>inlay hints</li><li>phantom text</li><li>diagnostics</li><li>gutter icons</li><li>fold regions</li><li>各类 guide 与 highlight</li></ul><h3 id="completion" tabindex="-1">Completion <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;Completion&quot;">​</a></h3><p>Completion providers 可以返回：</p><ul><li>popup items</li><li>anchors</li><li>selection updates</li><li>自定义条目渲染相关数据</li></ul><h3 id="copilot-风格-inline-suggestions" tabindex="-1">Copilot 风格 Inline Suggestions <a class="header-anchor" href="#copilot-风格-inline-suggestions" aria-label="Permalink to &quot;Copilot 风格 Inline Suggestions&quot;">​</a></h3><p>SweetEditor 也支持在 Compose 层提供 copilot 风格的 inline suggestions：</p><ul><li>显示 <code>InlineSuggestion</code></li><li>以 phantom text 方式渲染</li><li>用 <code>Tab</code> 接受</li><li>用 <code>Escape</code> 关闭</li></ul><h2 id="相关指南" tabindex="-1">相关指南 <a class="header-anchor" href="#相关指南" aria-label="Permalink to &quot;相关指南&quot;">​</a></h2><ul><li><a href="./theme-appearance">主题 / 外观</a></li><li><a href="./api-cookbook">API Cookbook</a></li><li><a href="./decorations">Decorations</a></li><li><a href="./completion">Completion</a></li><li><a href="./copilot-inline-suggestion">Copilot / Inline Suggestion</a></li></ul><h2 id="示例模块" tabindex="-1">示例模块 <a class="header-anchor" href="#示例模块" aria-label="Permalink to &quot;示例模块&quot;">​</a></h2><ul><li><a href="https://github.com/lumkit/SweetEditor-Compose/tree/main/example" target="_blank" rel="noreferrer">Example App</a></li><li><a href="https://github.com/lumkit/SweetEditor-Compose/tree/main/platform-demo" target="_blank" rel="noreferrer">Platform Demos</a></li></ul>',20)])])}const m=i(t,[["render",r]]);export{u as __pageData,m as default};
